class Configuration {
  static #instance;

  constructor() {
    this.environment = 'production';
  }

  static getInstance() {
    if (!Configuration.#instance) {
      Configuration.#instance = new Configuration();
    }
    return Configuration.#instance;
  }
}

const configA = Configuration.getInstance();
configA.environment = 'development';

const configB = Configuration.getInstance();
console.log(configB.environment); // 'development'
console.log(configA === configB);  // true

class NotificationFactory {
  static create(type) {
    if (type === 'email') return new EmailNotification();
    if (type === 'sms') return new SmsNotification();
    throw new Error('Unknown type');
  }
}

const notif = NotificationFactory.create('email');
notif.send('Welcome!');

class Subject {
  #observers = [];
  subscribe(fn) { this.#observers.push(fn); }
  notify(data) { this.#observers.forEach((fn) => fn(data)); }
}

const fishPrice = new Subject();
fishPrice.subscribe((p) => console.log('New price:', p));
fishPrice.notify(1500);

const emptyMarket = new Subject();
emptyMarket.notify('nothing to report'); // no subscribers: forEach does nothing, no error thrown

const strategies = {
  card: (amount) => amount * 1.02,
  wave: (amount) => amount * 1.01,
  cash: (amount) => amount,
};

function calculateTotal(amount, mode) {
  return strategies[mode](amount);
}

function calculateTotalSafely(amount, mode) {
  if (!strategies[mode]) throw new Error(`Unknown payment mode: ${mode}`);
  return strategies[mode](amount);
}

// External API imposed on us, different shape
class LegacyService { fetchData() { return { d: [1,2,3] }; } }

// Adapter to the interface expected by our app
class ServiceAdapter {
  #service = new LegacyService();
  getData() { return this.#service.fetchData().d; }
}

class UnstableLegacyService { fetchData() { return null; } }
class RobustServiceAdapter {
  #service = new UnstableLegacyService();
  getData() { return this.#service.fetchData()?.d ?? []; }
}

function withLog(fn) {
  return (...args) => {
    console.log('Called with', args);
    return fn(...args);
  };
}

const add = (a, b) => a + b;
const addWithLog = withLog(add);
addWithLog(2, 3); // logs, then 5

class PizzaBuilder {
  #pizza = { toppings: [] };
  addTopping(t) { this.#pizza.toppings.push(t); return this; }
  size(s) { this.#pizza.size = s; return this; }
  build() { return this.#pizza; }
}

const pizza = new PizzaBuilder()
  .size('L')
  .addTopping('thiof')
  .addTopping('onions')
  .build();

const pizzaWithoutSize = new PizzaBuilder()
  .addTopping('mafe')
  .build();
console.log(pizzaWithoutSize.size); // undefined: no default value if .size() is never called
